import csv
BAD={'ERROR','UNKNOWN',''}
def clean(s):
    v=(s or '').strip(); return None if v in BAD else v
def num(s):
    try: return float(clean(s))
    except (TypeError,ValueError): return None
maxdiff=0.0; item_ok_ts_bad=0; item_bad=0; n=0
with open(r'<实验根目录>\ab-v3\datasets\cafe_sales_dirty.csv',newline='',encoding='utf-8-sig') as f:
