        n+=1; item=clean(row['Item']); q=num(row['Quantity']); ppu=num(row['Price Per Unit']); ts=num(row['Total Spent'])
        if ts is not None and q is not None and ppu is not None:
            maxdiff=max(maxdiff,abs(ts-q*ppu))
        if item is not None:
            if ts is None and not(q is not None and ppu is not None): item_ok_ts_bad+=1
        else: item_bad+=1
print('total',n,'maxdiff',round(maxdiff,6),'item_ok_but_ts_unfixable',item_ok_ts_bad,'item_bad',item_bad)
"

